		assertFalse(hiddenResult.hasBinding("value"));
		assertTrue(BindingSetOrigin.of(hiddenResult).isRequest("value"));
		assertSame(REQUEST, BindingSetOrigin.of(hiddenResult).parameterValue("value"));

