	@ParameterizedTest(name = "optimized={0}, output={1}")
	@MethodSource("requestRows")
	void nullContributionsKeepTheActualRequestMappingLikeValues(boolean optimized, Output output) {
		BindingSet request = BindingSetOrigin.requestInput(binding(REQUEST));
		assertEquals(REQUEST, MATCH);
		assertFalse(REQUEST == MATCH);
		List<Value> tuple = output.cells();
		TupleFunctionCall call = call(tuple.size());
		TrackingFunction function = new TrackingFunction(List.of(tuple));
		BindingSet input;
		if (optimized) {
			new BindingAssignerOptimizer().optimize(new QueryRoot(call), null, request);
			for (Var var : call.getResultVars()) {
				assertTrue(var.hasValue());
				assertTrue(var.hasApiInputOrigin());
				assertFalse(var.isConstant());
				assertSame(REQUEST, var.getValue());
			}
			input = BindingSetOrigin.optimizationInput(request);
			assertFalse(input.hasBinding("value"));
			assertSame(REQUEST, BindingSetOrigin.of(input).parameterValue("value"));
		} else {
			input = request;
			assertFalse(call.getResultVars().get(0).hasValue());
		}
		// The reference receives the mapping the tuple's real materializer is entitled to supply.
		BindingSet referenceInput = optimized
				? BindingSetOrigin.materializeParameters(input, call.getResultVars(), new QueryEvaluationContext.Minimal(null))
				: input;
		TupleExpr ordinary = null;
		for (Value value : tuple) {
			ordinary = ordinary == null ? values(value) : new Join(ordinary, values(value));
		}
		List<BindingSet> expected = drain(strategy(null).precompile(ordinary).evaluate(referenceInput));
		assertEquals(output.conflicting ? 0 : 1, expected.size(), "ordinary positional VALUES oracle");
		if (!expected.isEmpty()) {
			assertSame(REQUEST, expected.getFirst().getValue("value"));
		}

		List<BindingSet> actual = drain(strategy(function).precompile(call).evaluate(input));
		assertEquals(expected.size(), actual.size());
		if (!actual.isEmpty()) {
			BindingSet row = actual.getFirst();
			assertEquals(Set.of("value"), row.getBindingNames());
			assertSame(REQUEST, row.getValue("value"));
			assertTrue(BindingSetOrigin.of(row).isLocal("value"), "prepared tuple declaration is a producer event");
			assertFalse(BindingSetOrigin.of(row).isRequest("value"));
			if (optimized) {
				assertSame(REQUEST, BindingSetOrigin.of(row).retainedParametersForTransport().get("value"));
			}
		}
		assertEquals(1, function.opens);
		assertEquals(1, function.closes);
	}

	@ParameterizedTest
	@EnumSource(Authority.class)
	void foldedNullNeedsItsMatchingUnmaskedRuntimeRequest(Authority authority) {
		Var folded = foldedVar();
		BindingSet input = authority.input();
		assertFalse(input.hasBinding("value"));
		if (authority != Authority.NONE) {
			assertTrue(BindingSetOrigin.isTrackedInput(input));
			assertSame(authority == Authority.CONFLICT ? OTHER : REQUEST,
					BindingSetOrigin.of(input).retainedParametersForTransport().get("value"));
			assertEquals(authority != Authority.LOCAL_MASK, BindingSetOrigin.of(input).isRequest("value"));
			assertEquals(authority == Authority.LOCAL_MASK, BindingSetOrigin.of(input).isLocal("value"));
		}
		QueryBindingSet suppliedGraph = new QueryBindingSet();
		GraphFrameBindings.supply(suppliedGraph, "hiddenGraph", GRAPH);
		input = GraphFrameBindings.preserve(suppliedGraph, new QueryBindingSet(input));
		assertSame(GRAPH, GraphFrameBindings.from(input).retainedParametersForTransport().get("hiddenGraph"));
		assertFalse(GraphFrameBindings.isSupplied(input, "hiddenGraph"));
		TrackingFunction function = new TrackingFunction(List.of(Arrays.asList((Value) null)));
		TupleFunctionCall call = call(1); call.setResultVars(List.of(folded));
		List<BindingSet> rows = drain(strategy(function).precompile(call).evaluate(input));
		assertEquals(authority == Authority.MATCH ? 1 : 0, rows.size());
		if (!rows.isEmpty()) {
			assertSame(REQUEST, rows.getFirst().getValue("value"));
			assertTrue(BindingSetOrigin.of(rows.getFirst()).isLocal("value"));
			assertSame(GRAPH, GraphFrameBindings.from(rows.getFirst()).retainedParametersForTransport().get("hiddenGraph"));
			assertFalse(GraphFrameBindings.isSupplied(rows.getFirst(), "hiddenGraph"));
		}
		assertEquals(1, function.opens); assertEquals(1, function.closes);
	}

